60	  /**
61	   * This array contains triplets of references. For each i-th storage, the
62	   * block belongs to triplets[3*i] is the reference to the
63	   * {@link DatanodeStorageInfo} and triplets[3*i+1] and triplets[3*i+2] are
64	   * references to the previous and the next blocks, respectively, in the list
65	   * of blocks belonging to this storage.
66	   *
67	   * Using previous and next in Object triplets is done instead of a
68	   * {@link LinkedList} list to efficiently use memory. With LinkedList the cost
69	   * per replica is 42 bytes (LinkedList#Entry object per replica) versus 16
70	   * bytes using the triplets.
71	   */
72	  protected Object[] triplets;
73	
74	  private BlockUnderConstructionFeature uc;
