77	   * Construct an entry for blocksmap
78	   * @param size the block's replication factor, or the total number of blocks
79	   *             in the block group
80	   */
81	  public BlockInfo(short size) {
82	    this.triplets = new Object[3 * size];
83	    this.bcId = INVALID_INODE_ID;
84	    this.replication = isStriped() ? 0 : size;
85	  }
