127	  DatanodeStorageInfo getStorageInfo(int index) {
128	    assert this.triplets != null : "BlockInfo is not initialized";
129	    assert index >= 0 && index*3 < triplets.length : "Index is out of bound";
130	    return (DatanodeStorageInfo)triplets[index*3];
