231	  /**
232	   * Find specified DatanodeStorageInfo.
233	   * @return DatanodeStorageInfo or null if not found.
234	   */
235	  DatanodeStorageInfo findStorageInfo(DatanodeDescriptor dn) {
236	    int len = getCapacity();
237	    DatanodeStorageInfo providedStorageInfo = null;
238	    for(int idx = 0; idx < len; idx++) {
239	      DatanodeStorageInfo cur = getStorageInfo(idx);
240	      if(cur != null) {
241	        if (cur.getStorageType() == StorageType.PROVIDED) {
242	          // if block resides on provided storage, only match the storage ids
243	          if (dn.getStorageInfo(cur.getStorageID()) != null) {
244	            // do not return here as we have to check the other
245	            // DatanodeStorageInfos for this block which could be local
246	            providedStorageInfo = cur;
247	          }
248	        } else if (cur.getDatanodeDescriptor() == dn) {
249	          return cur;
250	        }
251	      }
252	    }
253	    return providedStorageInfo;
254	  }
255	
256	  /**
257	   * Find specified DatanodeStorageInfo.
258	   * @return index or -1 if not found.
259	   */
260	  int findStorageInfo(DatanodeStorageInfo storageInfo) {
261	    int len = getCapacity();
262	    for(int idx = 0; idx < len; idx++) {
263	      DatanodeStorageInfo cur = getStorageInfo(idx);
264	      if (cur == storageInfo) {
265	        return idx;
266	      }
267	    }
268	    return -1;
269	  }
270	
271	  /**
272	   * Insert this block into the head of the list of blocks
273	   * related to the specified DatanodeStorageInfo.
274	   * If the head is null then form a new list.
275	   * @return current block as the new head of the list.
276	   */
277	  BlockInfo listInsert(BlockInfo head, DatanodeStorageInfo storage) {
278	    int dnIndex = this.findStorageInfo(storage);
279	    assert dnIndex >= 0 : "Data node is not found: current";
280	    assert getPrevious(dnIndex) == null && getNext(dnIndex) == null :
281	        "Block is already in the list and cannot be inserted.";
282	    this.setPrevious(dnIndex, null);
283	    this.setNext(dnIndex, head);
284	    if (head != null) {
285	      head.setPrevious(head.findStorageInfo(storage), this);
286	    }
287	    return this;
288	  }
289	
290	  /**
291	   * Remove this block from the list of blocks
292	   * related to the specified DatanodeStorageInfo.
293	   * If this block is the head of the list then return the next block as
294	   * the new head.
295	   * @return the new head of the list or null if the list becomes
296	   * empy after deletion.
297	   */
298	  BlockInfo listRemove(BlockInfo head, DatanodeStorageInfo storage) {
299	    if (head == null) {
300	      return null;
301	    }
302	    int dnIndex = this.findStorageInfo(storage);
303	    if (dnIndex < 0) { // this block is not on the data-node list
304	      return head;
305	    }
306	
307	    BlockInfo next = this.getNext(dnIndex);
308	    BlockInfo prev = this.getPrevious(dnIndex);
309	    this.setNext(dnIndex, null);
310	    this.setPrevious(dnIndex, null);
311	    if (prev != null) {
312	      prev.setNext(prev.findStorageInfo(storage), next);
313	    }
314	    if (next != null) {
315	      next.setPrevious(next.findStorageInfo(storage), prev);
316	    }
317	    if (this == head) { // removing the head
318	      head = next;
319	    }
320	    return head;
321	  }
322	
323	  /**
324	   * Remove this block from the list of blocks related to the specified
325	   * DatanodeDescriptor. Insert it into the head of the list of blocks.
326	   *
327	   * @return the new head of the list.
328	   */
329	  public BlockInfo moveBlockToHead(BlockInfo head, DatanodeStorageInfo storage,
330	      int curIndex, int headIndex) {
331	    if (head == this) {
332	      return this;
333	    }
334	    BlockInfo next = this.setNext(curIndex, head);
335	    BlockInfo prev = this.setPrevious(curIndex, null);
336	
337	    head.setPrevious(headIndex, this);
338	    prev.setNext(prev.findStorageInfo(storage), next);
339	    if (next != null) {
340	      next.setPrevious(next.findStorageInfo(storage), prev);
341	    }
342	    return this;
343	  }
