391	    final BlockUCState state = getBlockUCState();
392	    return state.equals(BlockUCState.COMPLETE) ||
393	        state.equals(BlockUCState.COMMITTED);
394	  }
395	
396	  /**
397	   * Add/Update the under construction feature.
398	   */
399	  public void convertToBlockUnderConstruction(BlockUCState s,
400	      DatanodeStorageInfo[] targets) {
401	    if (isComplete()) {
402	      uc = new BlockUnderConstructionFeature(this, s, targets,
403	          this.getBlockType());
404	    } else {
405	      // the block is already under construction
406	      uc.setBlockUCState(s);
407	      uc.setExpectedLocations(this, targets, this.getBlockType());
408	    }
409	  }
410	
411	  /**
412	   * Convert an under construction block to complete.
413	   */
414	  void convertToCompleteBlock() {
415	    assert getBlockUCState() != BlockUCState.COMPLETE :
416	        "Trying to convert a COMPLETE block";
417	    uc = null;
418	  }
