420	  /**
421	   * Process the recorded replicas. When about to commit or finish the
422	   * pipeline recovery sort out bad replicas.
423	   * @param genStamp  The final generation stamp for the block.
424	   * @return staleReplica's List.
425	   */
426	  public List<ReplicaUnderConstruction> setGenerationStampAndVerifyReplicas(
427	      long genStamp) {
428	    Preconditions.checkState(uc != null && !isComplete());
429	    // Set the generation stamp for the block.
430	    setGenerationStamp(genStamp);
431	
432	    return uc.getStaleReplicas(genStamp);
433	  }
