435	  /**
436	   * Commit block's length and generation stamp as reported by the client.
437	   * Set block state to {@link BlockUCState#COMMITTED}.
438	   * @param block - contains client reported block length and generation
439	   * @return staleReplica's List.
440	   * @throws IOException if block ids are inconsistent.
441	   */
442	  List<ReplicaUnderConstruction> commitBlock(Block block) throws IOException {
443	    if (getBlockId() != block.getBlockId()) {
444	      throw new IOException("Trying to commit inconsistent block: id = "
445	          + block.getBlockId() + ", expected id = " + getBlockId());
446	    }
447	    Preconditions.checkState(!isComplete());
448	    uc.commit();
449	    this.setNumBytes(block.getNumBytes());
450	    // Sort out invalid replicas.
451	    return setGenerationStampAndVerifyReplicas(block.getGenerationStamp());
452	  }
