423	    /**
424	     * Construct an RPC server.
425	     * 
426	     * @param protocolClass the class of protocol
427	     * @param protocolImpl the protocolImpl whose methods will be called
428	     * @param conf the configuration to use
429	     * @param bindAddress the address to bind on to listen for connection
430	     * @param port the port to listen for connections on
431	     * @param numHandlers the number of method handler threads to run
432	     * @param verbose whether each call should be logged
433	     * @param portRangeConfig A config parameter that can be used to restrict
434	     * the range of ports used when port is 0 (an ephemeral port)
435	     * @param alignmentContext provides server state info on client responses
436	     */
437	    public Server(Class<?> protocolClass, Object protocolImpl,
438	        Configuration conf, String bindAddress, int port, int numHandlers,
439	        int numReaders, int queueSizePerHandler, boolean verbose,
440	        SecretManager<? extends TokenIdentifier> secretManager, 
441	        String portRangeConfig, AlignmentContext alignmentContext)
442	        throws IOException {
443	      super(protocolClass, protocolImpl, conf, bindAddress, port, numHandlers,
444	          numReaders, queueSizePerHandler, verbose, secretManager,
445	          portRangeConfig, alignmentContext);
446	    }
447	
448	    /**
449	     * This implementation is same as
450	     * ProtobufRpcEngine2.Server.ProtobufInvoker#call(..)
451	     * except this implementation uses non-shaded protobuf classes from legacy
452	     * protobuf version (default 2.5.0).
453	     */
454	    static RpcWritable processCall(RPC.Server server,
455	        String connectionProtocolName, RpcWritable.Buffer request,
456	        String methodName, ProtoClassProtoImpl protocolImpl) throws Exception {
457	      BlockingService service = (BlockingService) protocolImpl.protocolImpl;
458	      MethodDescriptor methodDescriptor = service.getDescriptorForType()
459	          .findMethodByName(methodName);
460	      if (methodDescriptor == null) {
461	        String msg = "Unknown method " + methodName + " called on "
462	                              + connectionProtocolName + " protocol.";
463	        LOG.warn(msg);
464	        throw new RpcNoSuchMethodException(msg);
465	      }
466	      Message prototype = service.getRequestPrototype(methodDescriptor);
467	      Message param = request.getValue(prototype);
468	
469	      Message result;
470	      Call currentCall = Server.getCurCall().get();
471	      try {
472	        server.rpcDetailedMetrics.init(protocolImpl.protocolClass);
473	        CURRENT_CALL_INFO.set(new CallInfo(server, methodName));
474	        currentCall.setDetailedMetricsName(methodName);
475	        result = service.callBlockingMethod(methodDescriptor, null, param);
476	        // Check if this needs to be a deferred response,
477	        // by checking the ThreadLocal callback being set
478	        if (currentCallback.get() != null) {
479	          currentCall.deferResponse();
480	          currentCallback.set(null);
481	          return null;
482	        }
483	      } catch (ServiceException e) {
484	        Exception exception = (Exception) e.getCause();
485	        currentCall
486	            .setDetailedMetricsName(exception.getClass().getSimpleName());
487	        throw (Exception) e.getCause();
488	      } catch (Exception e) {
489	        currentCall.setDetailedMetricsName(e.getClass().getSimpleName());
490	        throw e;
491	      } finally {
492	        CURRENT_CALL_INFO.set(null);
493	      }
494	      return RpcWritable.wrap(result);
495	    }
496	  }
