659	  protected Response put(
660	      final UserGroupInformation ugi,
661	      final DelegationParam delegation,
662	      final UserParam username,
663	      final DoAsParam doAsUser,
664	      final String fullpath,
665	      final PutOpParam op,
666	      final DestinationParam destination,
667	      final OwnerParam owner,
668	      final GroupParam group,
669	      final PermissionParam permission,
670	      final UnmaskedPermissionParam unmaskedPermission,
671	      final OverwriteParam overwrite,
672	      final BufferSizeParam bufferSize,
673	      final ReplicationParam replication,
674	      final BlockSizeParam blockSize,
675	      final ModificationTimeParam modificationTime,
676	      final AccessTimeParam accessTime,
677	      final RenameOptionSetParam renameOptions,
678	      final CreateParentParam createParent,
679	      final TokenArgumentParam delegationTokenArgument,
680	      final AclPermissionParam aclPermission,
681	      final XAttrNameParam xattrName,
682	      final XAttrValueParam xattrValue,
683	      final XAttrSetFlagParam xattrSetFlag,
684	      final SnapshotNameParam snapshotName,
685	      final OldSnapshotNameParam oldSnapshotName,
686	      final ExcludeDatanodesParam exclDatanodes,
687	      final CreateFlagParam createFlagParam,
688	      final NoRedirectParam noredirectParam,
689	      final StoragePolicyParam policyName,
690	      final ECPolicyParam ecpolicy,
691	      final NameSpaceQuotaParam namespaceQuota,
692	      final StorageSpaceQuotaParam storagespaceQuota,
693	      final StorageTypeParam storageType
694	      ) throws IOException, URISyntaxException {
695	    final Configuration conf = (Configuration)context.getAttribute(JspHelper.CURRENT_CONF);
696	    final ClientProtocol cp = getRpcClientProtocol();
697	
698	    switch(op.getValue()) {
699	    case CREATE:
700	    {
701	      final NameNode namenode = (NameNode)context.getAttribute("name.node");
702	      final URI uri = redirectURI(null, namenode, ugi, delegation, username,
703	          doAsUser, fullpath, op.getValue(), -1L, blockSize.getValue(conf),
704	          exclDatanodes.getValue(), permission, unmaskedPermission,
705	          overwrite, bufferSize, replication, blockSize, createParent,
706	          createFlagParam);
707	      if(!noredirectParam.getValue()) {
708	        return Response.temporaryRedirect(uri)
709	          .type(MediaType.APPLICATION_OCTET_STREAM).build();
710	      } else {
711	        final String js = JsonUtil.toJsonString("Location", uri);
712	        return Response.ok(js).type(MediaType.APPLICATION_JSON).build();
713	      }
714	    }
715	    case MKDIRS:
716	    {
717	      FsPermission masked = unmaskedPermission.getValue() == null ?
718	          permission.getDirFsPermission() :
719	          FsCreateModes.create(permission.getDirFsPermission(),
720	              unmaskedPermission.getDirFsPermission());
721	      final boolean b = cp.mkdirs(fullpath, masked, true);
722	      final String js = JsonUtil.toJsonString("boolean", b);
723	      return Response.ok(js).type(MediaType.APPLICATION_JSON).build();
724	    }
725	    case CREATESYMLINK:
726	    {
727	      validateOpParams(op, destination);
728	      cp.createSymlink(destination.getValue(), fullpath,
729	          PermissionParam.getDefaultSymLinkFsPermission(),
730	          createParent.getValue());
731	      return Response.ok().type(MediaType.APPLICATION_OCTET_STREAM).build();
732	    }
733	    case RENAME:
734	    {
735	      validateOpParams(op, destination);
736	      final EnumSet<Options.Rename> s = renameOptions.getValue();
737	      if (s.isEmpty()) {
738	        final boolean b = cp.rename(fullpath, destination.getValue());
739	        final String js = JsonUtil.toJsonString("boolean", b);
740	        return Response.ok(js).type(MediaType.APPLICATION_JSON).build();
741	      } else {
742	        cp.rename2(fullpath, destination.getValue(),
743	            s.toArray(new Options.Rename[s.size()]));
744	        return Response.ok().type(MediaType.APPLICATION_OCTET_STREAM).build();
745	      }
746	    }
747	    case SETREPLICATION:
748	    {
749	      final boolean b = cp.setReplication(fullpath, replication.getValue(conf));
750	      final String js = JsonUtil.toJsonString("boolean", b);
751	      return Response.ok(js).type(MediaType.APPLICATION_JSON).build();
752	    }
753	    case SETOWNER:
754	    {
755	      if (owner.getValue() == null && group.getValue() == null) {
