502	  /**
503	   * This method creates and returns reference of the first intercepter in the
504	   * chain of request intercepter instances.
505	   *
506	   * @return the reference of the first intercepter in the chain
507	   */
508	  @VisibleForTesting
509	  protected ClientRequestInterceptor createRequestInterceptorChain() {
510	    Configuration conf = getConfig();
511	
512	    List<String> interceptorClassNames = getInterceptorClassNames(conf);
513	
514	    ClientRequestInterceptor pipeline = null;
515	    ClientRequestInterceptor current = null;
516	    for (String interceptorClassName : interceptorClassNames) {
517	      try {
518	        Class<?> interceptorClass = conf.getClassByName(interceptorClassName);
519	        if (ClientRequestInterceptor.class.isAssignableFrom(interceptorClass)) {
520	          ClientRequestInterceptor interceptorInstance =
521	              (ClientRequestInterceptor) ReflectionUtils
522	                  .newInstance(interceptorClass, conf);
523	          if (pipeline == null) {
524	            pipeline = interceptorInstance;
525	            current = interceptorInstance;
526	            continue;
527	          } else {
528	            current.setNextInterceptor(interceptorInstance);
529	            current = interceptorInstance;
530	          }
531	        } else {
532	          throw new YarnRuntimeException(
533	              "Class: " + interceptorClassName + " not instance of "
534	                  + ClientRequestInterceptor.class.getCanonicalName());
535	        }
536	      } catch (ClassNotFoundException e) {
537	        throw new YarnRuntimeException(
538	            "Could not instantiate ApplicationClientRequestInterceptor: "
539	                + interceptorClassName,
540	            e);
541	      }
542	    }
543	
544	    if (pipeline == null) {
545	      throw new YarnRuntimeException(
546	          "RequestInterceptor pipeline is not configured in the system");
547	    }
548	    return pipeline;
549	  }
