551	  /**
552	   * Initializes the request intercepter pipeline for the specified application.
553	   *
554	   * @param user
555	   */
556	  private RequestInterceptorChainWrapper initializePipeline(String user) {
557	    synchronized (this.userPipelineMap) {
558	      if (this.userPipelineMap.containsKey(user)) {
559	        LOG.info("Request to start an already existing user: {}"
560	            + " was received, so ignoring.", user);
561	        return userPipelineMap.get(user);
562	      }
563	
564	      RequestInterceptorChainWrapper chainWrapper =
565	          new RequestInterceptorChainWrapper();
566	      try {
567	        // We should init the pipeline instance after it is created and then
568	        // add to the map, to ensure thread safe.
569	        LOG.info("Initializing request processing pipeline for application "
570	            + "for the user: {}", user);
571	
572	        ClientRequestInterceptor interceptorChain =
573	            this.createRequestInterceptorChain();
574	        interceptorChain.init(user);
575	        chainWrapper.init(interceptorChain);
576	      } catch (Exception e) {
577	        LOG.error("Init ClientRequestInterceptor error for user: " + user, e);
578	        throw e;
579	      }
580	
581	      this.userPipelineMap.put(user, chainWrapper);
582	      return chainWrapper;
583	    }
584	  }
