554	              rootException = e;
555	            }
556	          } finally {
557	            if (rootException != null) {
558	              throw new ReconfigurationException(property, newVal,
559	                  getConf().get(property), rootException);
560	            }
561	          }
562	        }
563	        break;
564	      }
565	      case DFS_DATANODE_BALANCE_MAX_NUM_CONCURRENT_MOVES_KEY: {
566	        ReconfigurationException rootException = null;
567	        try {
568	          LOG.info("Reconfiguring {} to {}", property, newVal);
