570	          if (newVal == null) {
571	            // set to default
572	            movers = DFS_DATANODE_BALANCE_MAX_NUM_CONCURRENT_MOVES_DEFAULT;
573	          } else {
574	            movers = Integer.parseInt(newVal);
575	            if (movers <= 0) {
576	              rootException = new ReconfigurationException(
577	                  property,
578	                  newVal,
579	                  getConf().get(property),
580	                  new IllegalArgumentException(
581	                      "balancer max concurrent movers must be larger than 0"));
582	            }
583	          }
584	          boolean success = xserver.updateBalancerMaxConcurrentMovers(movers);
585	          if (!success) {
586	            rootException = new ReconfigurationException(
587	                property,
588	                newVal,
589	                getConf().get(property),
590	                new IllegalArgumentException(
591	                    "Could not modify concurrent moves thread count"));
592	          }
593	          return Integer.toString(movers);
594	        } catch (NumberFormatException nfe) {
595	          rootException = new ReconfigurationException(
596	              property, newVal, getConf().get(property), nfe);
597	        } finally {
598	          if (rootException != null) {
599	            LOG.warn(String.format(
600	                "Exception in updating balancer max concurrent movers %s to %s",
601	                property, newVal), rootException);
602	            throw rootException;
603	          }
604	        }
605	        break;
606	      }
607	      default:
