623	   * The ECN bit for the DataNode. The DataNode should return:
624	   * <ul>
625	   *   <li>ECN.DISABLED when ECN is disabled.</li>
626	   *   <li>ECN.SUPPORTED when ECN is enabled but the DN still has capacity.</li>
627	   *   <li>ECN.CONGESTED when ECN is enabled and the DN is congested.</li>
628	   * </ul>
629	   */
630	  public PipelineAck.ECN getECN() {
631	    if (!pipelineSupportECN) {
632	      return PipelineAck.ECN.DISABLED;
633	    }
634	    double load = ManagementFactory.getOperatingSystemMXBean()
635	        .getSystemLoadAverage();
636	    return load > NUM_CORES * CONGESTION_RATIO ? PipelineAck.ECN.CONGESTED :
637	        PipelineAck.ECN.SUPPORTED;
638	  }
