1158	  protected SubClusterId getApplicationHomeSubCluster(
1159	      ApplicationId applicationId) throws YarnException {
1160	    if (applicationId == null) {
1161	      LOG.error("ApplicationId is Null, Can't find in SubCluster.");
1162	      return null;
1163	    }
1164	
1165	    SubClusterId resultSubClusterId = null;
1166	
1167	    // try looking for applicationId in Home SubCluster
1168	    try {
1169	      resultSubClusterId = federationFacade.
1170	          getApplicationHomeSubCluster(applicationId);
1171	    } catch (YarnException ex) {
1172	      if(LOG.isDebugEnabled()){
1173	        LOG.debug("can't find applicationId = {} in home sub cluster, " +
1174	             " try foreach sub clusters.", applicationId);
1175	      }
1176	    }
1177	    if (resultSubClusterId != null) {
1178	      return resultSubClusterId;
1179	    }
1180	
1181	    // if applicationId not found in Home SubCluster,
1182	    // foreach Clusters
1183	    Map<SubClusterId, SubClusterInfo> subClusters =
1184	        federationFacade.getSubClusters(true);
1185	    for (SubClusterId subClusterId : subClusters.keySet()) {
1186	      try {
1187	        ApplicationClientProtocol clientRMProxy = getClientRMProxyForSubCluster(subClusterId);
1188	        if(clientRMProxy == null) {
1189	          continue;
1190	        }
1191	        GetApplicationReportRequest appReportRequest =
1192	            GetApplicationReportRequest.newInstance(applicationId);
1193	        GetApplicationReportResponse appReportResponse =
1194	            clientRMProxy.getApplicationReport(appReportRequest);
1195	
1196	        if(appReportResponse!=null && applicationId.equals(
1197	            appReportResponse.getApplicationReport().getApplicationId())){
1198	          resultSubClusterId = federationFacade.addApplicationHomeSubCluster(
1199	               ApplicationHomeSubCluster.newInstance(applicationId, subClusterId));
1200	          return resultSubClusterId;
1201	        }
1202	
1203	      } catch (Exception ex) {
1204	        if(LOG.isDebugEnabled()){
1205	          LOG.debug("Can't Find ApplicationId = {} in Sub Cluster!", applicationId);
1206	        }
1207	      }
1208	    }
1209	
1210	    String errorMsg =
1211	        String.format("Can't Found applicationId = %s in any sub clusters", applicationId);
1212	    throw new YarnException(errorMsg);
1213	  }
1214	}

