507	
508	    // If DFS_JOURNALNODE_HTTP_BIND_HOST_KEY exists then it overrides the
509	    // host name portion of DFS_JOURNALNODE_HTTP_ADDRESS_KEY.
510	    final String bindHost = configuration.getTrimmed(
511	        DFS_JOURNALNODE_HTTP_BIND_HOST_KEY);
512	    if (bindHost != null && !bindHost.isEmpty()) {
513	      bindAddress = new InetSocketAddress(bindHost, bindAddress.getPort());
514	    }
