34	/**
35	 * A handler for storing and setting auto created queue template settings.
36	 */
37	public class AutoCreatedQueueTemplate {
38	  public static final String AUTO_QUEUE_TEMPLATE_PREFIX =
39	      AUTO_QUEUE_CREATION_V2_PREFIX + "template.";
40	  public static final String AUTO_QUEUE_LEAF_TEMPLATE_PREFIX =
41	      AUTO_QUEUE_CREATION_V2_PREFIX + "leaf-template.";
42	  public static final String AUTO_QUEUE_PARENT_TEMPLATE_PREFIX =
43	      AUTO_QUEUE_CREATION_V2_PREFIX + "parent-template.";
44	
45	  private static final String WILDCARD_QUEUE = "*";
46	  private static final int MAX_WILDCARD_LEVEL = 1;
47	
48	  private final Map<String, String> templateProperties = new HashMap<>();
49	  private final Map<String, String> leafOnlyProperties = new HashMap<>();
50	  private final Map<String, String> parentOnlyProperties = new HashMap<>();
51	
52	  public AutoCreatedQueueTemplate(CapacitySchedulerConfiguration configuration,
53	                                  String queuePath) {
54	    setTemplateConfigEntries(configuration, queuePath);
55	  }
56	
57	  @VisibleForTesting
58	  public static String getAutoQueueTemplatePrefix(String queue) {
59	    return CapacitySchedulerConfiguration.getQueuePrefix(queue)
60	        + AUTO_QUEUE_TEMPLATE_PREFIX;
61	  }
62	
63	  /**
64	   * Get the common template properties specified for a parent queue.
65	   * @return template property names and values
66	   */
67	  public Map<String, String> getTemplateProperties() {
68	    return templateProperties;
69	  }
70	
71	  /**
72	   * Get the leaf specific template properties specified for a parent queue.
73	   * @return template property names and values
74	   */
75	  public Map<String, String> getLeafOnlyProperties() {
76	    return leafOnlyProperties;
77	  }
78	
79	  /**
80	   * Get the parent specific template properties specified for a parent queue.
81	   * @return template property names and values
82	   */
83	  public Map<String, String> getParentOnlyProperties() {
84	    return parentOnlyProperties;
85	  }
86	
87	  /**
88	   * Sets the common template properties and parent specific template
89	   * properties of a child queue based on its parent template settings.
90	 * @param conf configuration to set
91	   * @param childQueuePath child queue path used for prefixing the properties
92	   */
93	  public void setTemplateEntriesForChild(CapacitySchedulerConfiguration conf,
94	                                         String childQueuePath) {
95	    setTemplateEntriesForChild(conf, childQueuePath, false);
96	  }
97	
98	  /**
99	   * Sets the common template properties and leaf or parent specific template
100	   * properties of a child queue based on its parent template settings.
101	   * template settings.
102	   * @param conf configuration to set
103	   * @param isLeaf whether to include leaf specific template properties, or
104	   *               parent specific template properties
105	   * @param childQueuePath child queue path used for prefixing the properties
106	   */
107	  public void setTemplateEntriesForChild(CapacitySchedulerConfiguration conf,
108	                                         String childQueuePath,
109	                                         boolean isLeaf) {
110	    if (childQueuePath.equals(ROOT)) {
111	      return;
112	    }
113	
114	    ConfigurationProperties configurationProperties =
115	        conf.getConfigurationProperties();
116	
117	    // Get all properties that are explicitly set
118	    Set<String> alreadySetProps = configurationProperties
119	        .getPropertiesWithPrefix(CapacitySchedulerConfiguration
120	            .getQueuePrefix(childQueuePath)).keySet();
121	
122	    // Check template properties only set for leaf or parent queues
123	    Map<String, String> queueTypeSpecificTemplates = parentOnlyProperties;
124	    if (isLeaf) {
125	      queueTypeSpecificTemplates = leafOnlyProperties;
126	    }
127	
128	    for (Map.Entry<String, String> entry :
129	        queueTypeSpecificTemplates.entrySet()) {
130	      // Do not overwrite explicitly configured properties
131	      if (alreadySetProps.contains(entry.getKey())) {
132	        continue;
133	      }
134	      conf.set(CapacitySchedulerConfiguration.getQueuePrefix(
135	          childQueuePath) + entry.getKey(), entry.getValue());
136	    }
137	
138	    for (Map.Entry<String, String> entry : templateProperties.entrySet()) {
139	      // Do not overwrite explicitly configured properties or properties set
140	      // by queue type specific templates (parent-template and leaf-template)
141	      if (alreadySetProps.contains(entry.getKey())
142	          || queueTypeSpecificTemplates.containsKey(entry.getKey())) {
143	        continue;
144	      }
145	      conf.set(CapacitySchedulerConfiguration.getQueuePrefix(
146	          childQueuePath) + entry.getKey(), entry.getValue());
147	    }
148	  }
149	
150	  /**
151	   * Store the template configuration properties. Explicit templates always take
152	   * precedence over wildcard values. An example template precedence
153	   * hierarchy for root.a ParentQueue from highest to lowest:
154	   * yarn.scheduler.capacity.root.a.auto-queue-creation-v2.template.capacity
155	   * yarn.scheduler.capacity.root.*.auto-queue-creation-v2.template.capacity
156	   */
157	  private void setTemplateConfigEntries(CapacitySchedulerConfiguration configuration,
158	                                        String queuePath) {
159	    ConfigurationProperties configurationProperties =
160	        configuration.getConfigurationProperties();
161	
162	    List<String> queuePathParts = new ArrayList<>(Arrays.asList(
163	        queuePath.split("\\.")));
164	
165	    if (queuePathParts.size() <= 1 && !queuePath.equals(ROOT)) {
166	      // This is an invalid queue path
167	      return;
168	    }
169	    int queuePathMaxIndex = queuePathParts.size() - 1;
170	
171	    // start with the most explicit format (without wildcard)
172	    int wildcardLevel = 0;
173	    // root can not be wildcarded
174	    // MAX_WILDCARD_LEVEL will be configurable in the future
175	    int supportedWildcardLevel = Math.min(queuePathMaxIndex - 1,
176	        MAX_WILDCARD_LEVEL);
177	    // Allow root to have template properties
178	    if (queuePath.equals(ROOT)) {
179	      supportedWildcardLevel = 0;
180	    }
181	
182	    // Collect all template entries
183	    while (wildcardLevel <= supportedWildcardLevel) {
184	      String templateQueuePath = String.join(".", queuePathParts);
185	      // Get all configuration entries with
186	      // yarn.scheduler.capacity.<queuePath> prefix
187	      Map<String, String> queueProps = configurationProperties
188	          .getPropertiesWithPrefix(getQueuePrefix(templateQueuePath));
189	
190	      // Store template, parent-template and leaf-template properties
191	      for (Map.Entry<String, String> entry : queueProps.entrySet()) {
192	        storeConfiguredTemplates(entry.getKey(), entry.getValue());
193	      }
194	
195	      // Replace a queue part with a wildcard based on the wildcard level
196	      // eg. root.a -> root.*
197	      int queuePartToWildcard = queuePathMaxIndex - wildcardLevel;
198	      queuePathParts.set(queuePartToWildcard, WILDCARD_QUEUE);
199	
200	      ++wildcardLevel;
201	    }
202	  }
203	
204	  private void storeConfiguredTemplates(
205	      String templateKey, String templateValue) {
206	    String prefix = "";
207	    Map<String, String> properties = templateProperties;
208	
209	    if (templateKey.startsWith(AUTO_QUEUE_TEMPLATE_PREFIX)) {
210	      prefix = AUTO_QUEUE_TEMPLATE_PREFIX;
211	    } else if (templateKey.startsWith(AUTO_QUEUE_LEAF_TEMPLATE_PREFIX)) {
212	      prefix = AUTO_QUEUE_LEAF_TEMPLATE_PREFIX;
213	      properties = leafOnlyProperties;
214	    } else if (templateKey.startsWith(
215	        AUTO_QUEUE_PARENT_TEMPLATE_PREFIX)) {
216	      prefix = AUTO_QUEUE_PARENT_TEMPLATE_PREFIX;
217	      properties = parentOnlyProperties;
218	    }
219	
220	    if (!prefix.isEmpty()) {
221	      // Trim template prefix from key
222	      String key = templateKey.substring(prefix.length());
223	      // If an entry is already present, it had a higher precedence
224	      properties.putIfAbsent(key, templateValue);
225	    }
226	  }
227	}

