import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.text.SimpleDateFormat;
import java.util.Date;

public class T {
  static final String ISO8601DATEFORMAT = "yyyy-MM-dd'T'HH:mm:ss.SSSZ";
  static final DateTimeFormatter DATE_FORMAT =
      DateTimeFormatter.ofPattern("EEE MMM dd HH:mm:ss Z yyyy", Locale.US)
          .withZone(ZoneId.systemDefault());
  static final DateTimeFormatter ISO_FORMAT =
      DateTimeFormatter.ofPattern(ISO8601DATEFORMAT, Locale.US)
          .withZone(ZoneId.systemDefault());
  public static void main(String[] a) throws Exception {
    long now = System.currentTimeMillis();
    SimpleDateFormat sdf = new SimpleDateFormat("EEE MMM dd HH:mm:ss Z yyyy", Locale.US);
    SimpleDateFormat iso = new SimpleDateFormat(ISO8601DATEFORMAT, Locale.US);
    String newFmt = DATE_FORMAT.format(Instant.ofEpochMilli(now));
    String oldFmt = sdf.format(new Date(now));
    System.out.println("dateFmt new: " + newFmt);
    System.out.println("dateFmt old: " + oldFmt);
    System.out.println("dateFmt equal: " + newFmt.equals(oldFmt));
    String newIso = ISO_FORMAT.format(Instant.ofEpochMilli(now));
    String oldIso = iso.format(new Date(now));
    System.out.println("iso new: " + newIso + " old: " + oldIso + " equal: " + newIso.equals(oldIso));
    long rt = ZonedDateTime.parse(newIso, ISO_FORMAT).toInstant().toEpochMilli();
    System.out.println("roundtrip: " + (rt == now));
    long rtOffset = ZonedDateTime.parse("2017-01-02T03:04:05.678+0000", ISO_FORMAT).toInstant().toEpochMilli();
    System.out.println("offset parse: " + rtOffset + " expected: " + iso.parse("2017-01-02T03:04:05.678+0000").getTime());
  }
}
