36	  add_options("path", po::value<std::string>(),
37	              "The path to the directory that is snapshot-able");
38	  add_options("name", po::value<std::string>(), "The name of the snapshot");
39	
40	  // Register "path" and "name" as positional arguments.
41	  // We allow only two arguments to be passed to this tool. An exception is
42	  // thrown if more than two arguments are passed.
43	  pos_opt_desc_.add("path", 1);
44	  pos_opt_desc_.add("name", 1);
45	
46	  po::store(po::command_line_parser(argc_, argv_)
47	                .options(opt_desc_)
48	                .positional(pos_opt_desc_)
49	                .run(),
50	            opt_val_);
51	  po::notify(opt_val_);
52	  return true;
53	}
