1008	  private LocatedBlock refetchLocations(LocatedBlock block,
1009	      Collection<DatanodeInfo> ignoredNodes) throws IOException {
1010	    String errMsg = getBestNodeDNAddrPairErrorString(block.getLocations(),
1011	            dfsClient.getDeadNodes(this), ignoredNodes);
1012	    String blockInfo = block.getBlock() + " file=" + src;
1013	    if (failures >= dfsClient.getConf().getMaxBlockAcquireFailures()) {
1014	      String description = "Could not obtain block: " + blockInfo;
1015	      DFSClient.LOG.warn(description + errMsg
1016	          + ". Throwing a BlockMissingException");
1017	      throw new BlockMissingException(src, description,
1018	          block.getStartOffset());
1019	    }
1020	
1021	    DatanodeInfo[] nodes = block.getLocations();
1022	    if (nodes == null || nodes.length == 0) {
1023	      DFSClient.LOG.info("No node available for " + blockInfo);
1024	    }
1025	    DFSClient.LOG.info("Could not obtain " + block.getBlock()
1026	        + " from any node: " + errMsg
1027	        + ". Will get new block locations from namenode and retry...");
1028	    try {
1029	      // Introducing a random factor to the wait time before another retry.
1030	      // The wait time is dependent on # of failures and a random factor.
1031	      // At the first time of getting a BlockMissingException, the wait time
1032	      // is a random number between 0..3000 ms. If the first retry
1033	      // still fails, we will wait 3000 ms grace period before the 2nd retry.
1034	      // Also at the second retry, the waiting window is expanded to 6000 ms
1035	      // alleviating the request rate from the server. Similarly the 3rd retry
1036	      // will wait 6000ms grace period before retry and the waiting window is
1037	      // expanded to 9000ms.
1038	      final int timeWindow = dfsClient.getConf().getTimeWindow();
1039	      // grace period for the last round of attempt
1040	      double waitTime = timeWindow * failures +
1041	          // expanding time window for each failure
1042	          timeWindow * (failures + 1) *
1043	          ThreadLocalRandom.current().nextDouble();
1044	      DFSClient.LOG.warn("DFS chooseDataNode: got # " + (failures + 1) +
1045	          " IOException, will wait for " + waitTime + " msec.");
1046	      Thread.sleep((long)waitTime);
1047	    } catch (InterruptedException e) {
1048	      Thread.currentThread().interrupt();
1049	      throw new InterruptedIOException(
1050	          "Interrupted while choosing DataNode for read.");
1051	    }
1052	    clearLocalDeadNodes(); //2nd option is to remove only nodes[blockId]
