/**
 * Update the current requests per second from the requests
 * served since the last update.
 */
private void updateTotalRequestsPerSecond() {
  long now = Time.monotonicNow();
  long currentTotalRequests = totalRequests.get();
  long elapsedTime = now - lastUpdateTime;
  if (elapsedTime > 0) {
    totalRequestsPerSecond =
        (currentTotalRequests - lastTotalRequests) * 1000.0 / elapsedTime;
  }
  lastTotalRequests = currentTotalRequests;
  lastUpdateTime = now;
}

