87	      // Create a URL connection
88	      URLConnection conn = connectionFactory.openConnection(
89	          jmxURL, UserGroupInformation.isSecurityEnabled());
90	      conn.setConnectTimeout(5 * 1000);
91	      conn.setReadTimeout(5 * 1000);
