  // handler to be called, request counter, and a boolean to keep track if find
  // is done
  auto state = std::make_shared<GetContentSummaryState>(handler, 0, false);

  // Keep requesting more from Find until we process the entire listing. Call
  // handler when Find is done and request counter is 0.
  // Find guarantees that the handler will only be called once at a time so we
  // do not need locking in handlerFind.
  auto handlerFind =
      [fs, state](const hdfs::Status &status_find,
                  const std::vector<hdfs::StatInfo> &stat_infos,
                  bool has_more_results) -> bool {
    // For each result returned by Find we call async GetContentSummary with
    // the handler below. GetContentSummary DOES NOT guarantee that the handler
    // will only be called once at a time, so we DO need locking in
    // handlerGetContentSummary.
    auto handlerGetContentSummary = [state](const hdfs::Status &
                                                status_get_summary,
                                            const hdfs::ContentSummary &si) {
      std::lock_guard<std::mutex> guard(state->lock);
      std::cout << si.str_du() << std::endl;
      // Decrement the counter once since we are done with this async call
      if (!status_get_summary.ok() && state->status.ok()) {
        // We make sure we set state->status only on the first error.
        state->status = status_get_summary;
      }
      state->request_counter--;
      if (state->request_counter == 0 && state->find_is_done) {
        state->handler(state->status); // exit
      }
    };
    if (!stat_infos.empty() && state->status.ok()) {
      for (const hdfs::StatInfo &s : stat_infos) {
        // Launch an asynchronous call to GetContentSummary for every returned
        // result
        state->request_counter++;
        fs->GetContentSummary(s.full_path, handlerGetContentSummary);
      }
    }

    // Lock this section because handlerGetContentSummary might be accessing
    // the same shared variables simultaneously
    std::lock_guard<std::mutex> guard(state->lock);
    if (!status_find.ok() && state->status.ok()) {
      // We make sure we set state->status only on the first error.
      state->status = status_find;
    }
    if (!has_more_results) {
      state->find_is_done = true;
      if (state->request_counter == 0) {
        state->handler(state->status); // exit
      }
      return false;
    }
    return true;
  };

  if (!recursive) {
    // Asynchronous call to GetListing
    fs->GetListing(uri.get_path(), handlerFind);
  } else {
    // Asynchronous call to Find
    fs->Find(uri.get_path(), "*", hdfs::FileSystem::GetDefaultFindMaxDepth(),
