55	+
56	+    List<List<T>> result = new ArrayList<>();
57	+    int i=0;
58	+    while (i < originalList.size()) {
59	+      result.add(originalList.subList(i,
60	+              Math.min(i + pageSize, originalList.size())));
61	+      i = i + pageSize;
62	+    }
63	+    return result;
