489	  /**
490	   * This method actually executes the client-side SASL handshake.
491	   *
492	   * @param addr connection address
493	   * @param underlyingOut connection output stream
494	   * @param underlyingIn connection input stream
495	   * @param userName SASL user name
496	   * @param saslProps properties of SASL negotiation
497	   * @param callbackHandler for responding to SASL callbacks
498	   * @return new pair of streams, wrapped after SASL negotiation
499	   * @throws IOException for any error
500	   */
501	  private IOStreamPair doSaslHandshake(InetAddress addr,
502	      OutputStream underlyingOut, InputStream underlyingIn, String userName,
503	      Map<String, String> saslProps, CallbackHandler callbackHandler,
504	      Token<BlockTokenIdentifier> accessToken) throws IOException {
505	
506	    DataOutputStream out = new DataOutputStream(underlyingOut);
507	    DataInputStream in = new DataInputStream(underlyingIn);
508	
509	    SaslParticipant sasl= SaslParticipant.createClientSaslParticipant(userName,
510	        saslProps, callbackHandler);
511	
512	    out.writeInt(SASL_TRANSFER_MAGIC_NUMBER);
513	    out.flush();
514	
515	    try {
516	      // Start of handshake - "initial response" in SASL terminology.
517	      // The handshake secret can be null, this happens when client is running
518	      // a new version but the cluster does not have this feature.
519	      // In which case there will be no encrypted secret sent from NN.
520	      BlockTokenIdentifier blockTokenIdentifier =
521	          accessToken.decodeIdentifier();
522	      if (blockTokenIdentifier != null) {
523	        byte[] handshakeSecret =
524	            accessToken.decodeIdentifier().getHandshakeMsg();
525	        if (handshakeSecret == null || handshakeSecret.length == 0) {
526	          LOG.debug("Handshake secret is null, "
527	              + "sending without handshake secret.");
528	          sendSaslMessage(out, new byte[0]);
529	        } else {
530	          LOG.debug("Sending handshake secret.");
531	          BlockTokenIdentifier identifier = new BlockTokenIdentifier();
532	          identifier.readFields(new DataInputStream(
533	              new ByteArrayInputStream(accessToken.getIdentifier())));
534	          String bpid = identifier.getBlockPoolId();
535	          sendSaslMessageHandshakeSecret(out, new byte[0],
536	              handshakeSecret, bpid);
537	        }
538	      } else {
539	        LOG.debug("Block token id is null, sending without handshake secret.");
540	        sendSaslMessage(out, new byte[0]);
541	      }
542	
543	      // step 1
544	      byte[] remoteResponse = readSaslMessage(in);
545	      byte[] localResponse = sasl.evaluateChallengeOrResponse(remoteResponse);
546	      List<CipherOption> cipherOptions = null;
547	      String cipherSuites = conf.get(
548	          DFS_ENCRYPT_DATA_TRANSFER_CIPHER_SUITES_KEY);
549	      if (requestedQopContainsPrivacy(saslProps)) {
550	        // Negotiate cipher suites if configured.  Currently, the only supported
551	        // cipher suite is AES/CTR/NoPadding or SM4/CTR/Nopadding,
552	        // but the protocol allows multiple values for future expansion.
553	        if (cipherSuites != null && !cipherSuites.isEmpty()) {
554	          CipherOption option = null;
555	          if (cipherSuites.equals(CipherSuite.AES_CTR_NOPADDING.getName())) {
556	            option = new CipherOption(CipherSuite.AES_CTR_NOPADDING);
557	          } else if (cipherSuites.equals(
558	              CipherSuite.SM4_CTR_NOPADDING.getName())) {
559	            option = new CipherOption(CipherSuite.SM4_CTR_NOPADDING);
560	          } else {
561	            throw new IOException(String.format("Invalid cipher suite, %s=%s",
562	                DFS_ENCRYPT_DATA_TRANSFER_CIPHER_SUITES_KEY, cipherSuites));
563	          }
564	          cipherOptions = Lists.newArrayListWithCapacity(1);
565	          cipherOptions.add(option);
566	        }
567	      }
568	      sendSaslMessageAndNegotiationCipherOptions(out, localResponse,
569	          cipherOptions);
570	
571	      // step 2 (client-side only)
572	      SaslResponseWithNegotiatedCipherOption response =
573	          readSaslMessageAndNegotiatedCipherOption(in);
574	      localResponse = sasl.evaluateChallengeOrResponse(response.payload);
575	      assert localResponse == null;
576	
577	      // SASL handshake is complete
578	      checkSaslComplete(sasl, saslProps);
579	
580	      CipherOption cipherOption = null;
581	      if (sasl.isNegotiatedQopPrivacy()) {
582	        // Unwrap the negotiated cipher option
583	        cipherOption = unwrap(response.cipherOption, sasl);
584	        if (LOG.isDebugEnabled()) {
585	          if (cipherOption == null) {
586	            // No cipher suite is negotiated
587	            if (cipherSuites != null && !cipherSuites.isEmpty()) {
588	              // the client accepts some cipher suites, but the server does not.
589	              LOG.debug("Client accepts cipher suites {}, "
590	                      + "but server {} does not accept any of them",
591	                  cipherSuites, addr.toString());
592	            }
593	          } else {
594	            LOG.debug("Client using cipher suite {} with server {}",
595	                cipherOption.getCipherSuite().getName(), addr.toString());
596	          }
597	        }
598	      }
599	
600	      // If negotiated cipher option is not null, we will use it to create
601	      // stream pair.
602	      return cipherOption != null ? createStreamPair(
603	          conf, cipherOption, underlyingOut, underlyingIn, false) :
604	          sasl.createStreamPair(out, in);
605	    } catch (IOException ioe) {
606	      sendGenericSaslErrorMessage(out, ioe.getMessage());
607	      throw ioe;
608	    }
609	  }
610	}

