166	        StaticRouterRpcFairnessPolicyController.ERROR_MSG, handlerCount,
167	        totalDedicatedHandlers);
168	    assertTrue("Should contain error message: " + errorMsg,
169	        logs.getOutput().contains(errorMsg));
170	  }
171	
172	  private void verifyInstantiationError(Configuration conf, String ns, int handlerCount,
173	      int minimumHandler) {
174	    GenericTestUtils.LogCapturer logs = GenericTestUtils.LogCapturer.captureLogs(
175	        LoggerFactory.getLogger(StaticRouterRpcFairnessPolicyController.class));
176	    try {
177	      FederationUtil.newFairnessPolicyController(conf);
178	    } catch (IllegalArgumentException e) {
179	      // Ignore the exception as it is expected here.
180	    }
181	    String errorMsg = String.format(StaticRouterRpcFairnessPolicyController.ERROR_NS_MSG,
182	        DFS_ROUTER_FAIR_HANDLER_COUNT_KEY_PREFIX + ns, handlerCount, minimumHandler);
183	    assertTrue("Should contain error message: " + errorMsg, logs.getOutput().contains(errorMsg));
184	  }
185	
186	  private RouterRpcFairnessPolicyController getFairnessPolicyController(
187	      int handlers) {
188	    return FederationUtil.newFairnessPolicyController(createConf(handlers));
189	  }
190	
191	  private void verifyHandlerAllocation(
192	      RouterRpcFairnessPolicyController routerRpcFairnessPolicyController) {
193	    for (int i=0; i<10; i++) {
194	      assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns1"));
195	      assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns2"));
196	      assertTrue(
197	          routerRpcFairnessPolicyController.acquirePermit(CONCURRENT_NS));
198	    }
199	    assertFalse(routerRpcFairnessPolicyController.acquirePermit("ns1"));
200	    assertFalse(routerRpcFairnessPolicyController.acquirePermit("ns2"));
201	    assertFalse(routerRpcFairnessPolicyController.acquirePermit(CONCURRENT_NS));
202	
203	    routerRpcFairnessPolicyController.releasePermit("ns1");
204	    routerRpcFairnessPolicyController.releasePermit("ns2");
205	    routerRpcFairnessPolicyController.releasePermit(CONCURRENT_NS);
206	
207	    assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns1"));
208	    assertTrue(routerRpcFairnessPolicyController.acquirePermit("ns2"));
209	    assertTrue(routerRpcFairnessPolicyController.acquirePermit(CONCURRENT_NS));
210	  }
211	
212	  private Configuration createConf(int handlers) {
213	    Configuration conf = new HdfsConfiguration();
214	    conf.setInt(DFS_ROUTER_HANDLER_COUNT_KEY, handlers);
215	    conf.set(DFS_ROUTER_MONITOR_NAMENODE, nameServices);
216	    conf.setClass(
217	        RBFConfigKeys.DFS_ROUTER_FAIRNESS_POLICY_CONTROLLER_CLASS,
218	        StaticRouterRpcFairnessPolicyController.class,
219	        RouterRpcFairnessPolicyController.class);
220	    return conf;
221	  }
