65	/**
66	 * Negotiates SASL for DataTransferProtocol on behalf of a server.  There are
67	 * two possible supported variants of SASL negotiation: either a general-purpose
68	 * negotiation supporting any quality of protection, or a specialized
69	 * negotiation that enforces privacy as the quality of protection using a
70	 * cryptographically strong encryption key.
71	 *
72	 * This class is used in the DataNode for handling inbound connections.
73	 */
74	@InterfaceAudience.Private
75	public class SaslDataTransferServer {
76	
77	  private static final Logger LOG = LoggerFactory.getLogger(
78	    SaslDataTransferServer.class);
79	
80	  private final BlockPoolTokenSecretManager blockPoolTokenSecretManager;
81	  private final DNConf dnConf;
82	
83	  // Store the most recent successfully negotiated QOP,
84	  // for testing purpose only
85	  private String negotiatedQOP;
86	
87	  /**
88	   * Creates a new SaslDataTransferServer.
89	   *
90	   * @param dnConf configuration of DataNode
91	   * @param blockPoolTokenSecretManager used for checking block access tokens
92	   *   and encryption keys
93	   */
94	  public SaslDataTransferServer(DNConf dnConf,
95	      BlockPoolTokenSecretManager blockPoolTokenSecretManager) {
96	    this.blockPoolTokenSecretManager = blockPoolTokenSecretManager;
97	    this.dnConf = dnConf;
98	  }
99	
100	  /**
101	   * Receives SASL negotiation from a peer on behalf of a server.
102	   *
103	   * @param peer connection peer
104	   * @param underlyingOut connection output stream
105	   * @param underlyingIn connection input stream
106	   * @param xferPort data transfer port of DataNode accepting connection
107	   * @param datanodeId ID of DataNode accepting connection
108	   * @return new pair of streams, wrapped after SASL negotiation
109	   * @throws IOException for any error
110	   */
111	  public IOStreamPair receive(Peer peer, OutputStream underlyingOut,
112	      InputStream underlyingIn, int xferPort, DatanodeID datanodeId)
113	      throws IOException {
114	    if (dnConf.getEncryptDataTransfer()) {
115	      LOG.debug(
116	        "SASL server doing encrypted handshake for peer = {}, datanodeId = {}",
117	        peer, datanodeId);
118	      return getEncryptedStreams(peer, underlyingOut, underlyingIn);
119	    } else if (!UserGroupInformation.isSecurityEnabled()) {
120	      LOG.debug(
121	        "SASL server skipping handshake in unsecured configuration for "
122	        + "peer = {}, datanodeId = {}", peer, datanodeId);
123	      return new IOStreamPair(underlyingIn, underlyingOut);
124	    } else if (SecurityUtil.isPrivilegedPort(xferPort)) {
125	      LOG.debug(
126	        "SASL server skipping handshake in secured configuration for "
127	        + "peer = {}, datanodeId = {}", peer, datanodeId);
128	      return new IOStreamPair(underlyingIn, underlyingOut);
129	    } else if (dnConf.getSaslPropsResolver() != null) {
130	      LOG.debug(
131	        "SASL server doing general handshake for peer = {}, datanodeId = {}",
132	        peer, datanodeId);
133	      return getSaslStreams(peer, underlyingOut, underlyingIn);
134	    } else if (dnConf.getIgnoreSecurePortsForTesting()) {
135	      // It's a secured cluster using non-privileged ports, but no SASL.  The
136	      // only way this can happen is if the DataNode has
137	      // ignore.secure.ports.for.testing configured, so this is a rare edge case.
138	      LOG.debug(
139	        "SASL server skipping handshake in secured configuration with no SASL "
140	        + "protection configured for peer = {}, datanodeId = {}",
141	        peer, datanodeId);
142	      return new IOStreamPair(underlyingIn, underlyingOut);
143	    } else {
144	      // The error message here intentionally does not mention
145	      // ignore.secure.ports.for.testing.  That's intended for dev use only.
146	      // This code path is not expected to execute ever, because DataNode startup
147	      // checks for invalid configuration and aborts.
148	      throw new IOException(String.format("Cannot create a secured " +
149	        "connection if DataNode listens on unprivileged port (%d) and no " +
150	        "protection is defined in configuration property %s.",
151	        datanodeId.getXferPort(), DFS_DATA_TRANSFER_PROTECTION_KEY));
152	    }
153	  }
154	
