156	   * Receives SASL negotiation for specialized encrypted handshake.
157	   *
158	   * @param peer connection peer
159	   * @param underlyingOut connection output stream
160	   * @param underlyingIn connection input stream
161	   * @return new pair of streams, wrapped after SASL negotiation
162	   * @throws IOException for any error
163	   */
164	  private IOStreamPair getEncryptedStreams(Peer peer,
165	      OutputStream underlyingOut, InputStream underlyingIn) throws IOException {
166	    if (peer.hasSecureChannel() ||
167	        dnConf.getTrustedChannelResolver().isTrusted(getPeerAddress(peer))) {
168	      return new IOStreamPair(underlyingIn, underlyingOut);
169	    }
170	
171	    Map<String, String> saslProps = createSaslPropertiesForEncryption(
172	      dnConf.getEncryptionAlgorithm());
173	
174	    if (LOG.isDebugEnabled()) {
175	      LOG.debug("Server using encryption algorithm " +
176	        dnConf.getEncryptionAlgorithm());
177	    }
