192	   * for determining the password.  This interface is used to parameterize that
193	   * logic.  It's similar to a Guava Function, but we need to let it throw
194	   * exceptions.
195	   */
196	  private interface PasswordFunction {
197	
198	    /**
199	     * Returns the SASL password for the given user name.
200	     *
201	     * @param userName SASL user name
202	     * @return SASL password
203	     * @throws IOException for any error
