205	    char[] apply(String userName) throws IOException;
206	  }
207	
208	  /**
209	   * Sets user name and password when asked by the server-side SASL object.
210	   */
211	  private static final class SaslServerCallbackHandler
212	      implements CallbackHandler {
213	
214	    private final PasswordFunction passwordFunction;
215	
216	    /**
217	     * Creates a new SaslServerCallbackHandler.
218	     *
219	     * @param passwordFunction for determing the user's password
220	     */
221	    public SaslServerCallbackHandler(PasswordFunction passwordFunction) {
222	      this.passwordFunction = passwordFunction;
223	    }
224	
225	    @Override
226	    public void handle(Callback[] callbacks) throws IOException,
227	        UnsupportedCallbackException {
228	      NameCallback nc = null;
229	      PasswordCallback pc = null;
230	      AuthorizeCallback ac = null;
231	      for (Callback callback : callbacks) {
232	        if (callback instanceof AuthorizeCallback) {
233	          ac = (AuthorizeCallback) callback;
234	        } else if (callback instanceof PasswordCallback) {
235	          pc = (PasswordCallback) callback;
236	        } else if (callback instanceof NameCallback) {
237	          nc = (NameCallback) callback;
238	        } else if (callback instanceof RealmCallback) {
239	          continue; // realm is ignored
240	        } else {
241	          throw new UnsupportedCallbackException(callback,
242	              "Unrecognized SASL DIGEST-MD5 Callback: " + callback);
243	        }
244	      }
245	
246	      if (pc != null) {
247	        pc.setPassword(passwordFunction.apply(nc.getDefaultName()));
248	      }
249	
250	      if (ac != null) {
251	        ac.setAuthorized(true);
252	        ac.setAuthorizedID(ac.getAuthorizationID());
253	      }
254	    }
255	  }
256	
257	  /**
258	   * Given a secret manager and a username encoded for the encrypted handshake,
259	   * determine the encryption key.
260	   * 
261	   * @param userName containing the keyId, blockPoolId, and nonce.
262	   * @return secret encryption key.
263	   * @throws IOException
264	   */
265	  private byte[] getEncryptionKeyFromUserName(String userName)
266	      throws IOException {
267	    String[] nameComponents = userName.split(NAME_DELIMITER);
268	    if (nameComponents.length != 3) {
269	      throw new IOException("Provided name '" + userName + "' has " +
270	          nameComponents.length + " components instead of the expected 3.");
271	    }
272	    int keyId = Integer.parseInt(nameComponents[0]);
273	    String blockPoolId = nameComponents[1];
274	    byte[] nonce = Base64.decodeBase64(nameComponents[2]);
275	    return blockPoolTokenSecretManager.retrieveDataEncryptionKey(keyId,
276	        blockPoolId, nonce);
277	  }
278	
279	  /**
280	   * Receives SASL negotiation for general-purpose handshake.
281	   *
282	   * @param peer connection peer
283	   * @param underlyingOut connection output stream
284	   * @param underlyingIn connection input stream
285	   * @return new pair of streams, wrapped after SASL negotiation
286	   * @throws IOException for any error
287	   */
288	  private IOStreamPair getSaslStreams(Peer peer, OutputStream underlyingOut,
289	      InputStream underlyingIn) throws IOException {
290	    if (peer.hasSecureChannel() ||
291	        dnConf.getTrustedChannelResolver().isTrusted(getPeerAddress(peer))) {
292	      return new IOStreamPair(underlyingIn, underlyingOut);
293	    }
294	
295	    SaslPropertiesResolver saslPropsResolver = dnConf.getSaslPropsResolver();
296	    Map<String, String> saslProps = saslPropsResolver.getServerProperties(
297	      getPeerAddress(peer));
298	
299	    CallbackHandler callbackHandler = new SaslServerCallbackHandler(
300	      new PasswordFunction() {
301	        @Override
302	        public char[] apply(String userName) throws IOException {
303	          return buildServerPassword(userName);
304	        }
305	    });
306	    return doSaslHandshake(peer, underlyingOut, underlyingIn, saslProps,
307	        callbackHandler);
308	  }
309	
310	  /**
311	   * Calculates the expected correct password on the server side for the
312	   * general-purpose handshake.  The password consists of the block access
313	   * token's password (known to the DataNode via its secret manager).  This
314	   * expects that the client has supplied a user name consisting of its
315	   * serialized block access token identifier.
316	   *
317	   * @param userName SASL user name containing serialized block access token
318	   *   identifier
319	   * @return expected correct SASL password
320	   * @throws IOException for any error
321	   */    
322	  private char[] buildServerPassword(String userName) throws IOException {
323	    BlockTokenIdentifier identifier = deserializeIdentifier(userName);
324	    byte[] tokenPassword = blockPoolTokenSecretManager.retrievePassword(
325	      identifier);
326	    return (new String(Base64.encodeBase64(tokenPassword, false),
327	      Charsets.UTF_8)).toCharArray();
328	  }
329	
330	  /**
331	   * Deserializes a base64-encoded binary representation of a block access
332	   * token.
333	   *
334	   * @param str String to deserialize
335	   * @return BlockTokenIdentifier deserialized from str
336	   * @throws IOException if there is any I/O error
337	   */
338	  private BlockTokenIdentifier deserializeIdentifier(String str)
339	      throws IOException {
340	    BlockTokenIdentifier identifier = new BlockTokenIdentifier();
341	    identifier.readFields(new DataInputStream(new ByteArrayInputStream(
342	      Base64.decodeBase64(str))));
343	    return identifier;
344	  }
345	
346	  @VisibleForTesting
347	  public String getNegotiatedQOP() {
348	    return negotiatedQOP;
349	  }
350	
351	  /**
352	   * This method actually executes the server-side SASL handshake.
353	   *
354	   * @param peer connection peer
355	   * @param underlyingOut connection output stream
356	   * @param underlyingIn connection input stream
357	   * @param saslProps properties of SASL negotiation
358	   * @param callbackHandler for responding to SASL callbacks
359	   * @return new pair of streams, wrapped after SASL negotiation
360	   * @throws IOException for any error
361	   */
362	  private IOStreamPair doSaslHandshake(Peer peer, OutputStream underlyingOut,
363	      InputStream underlyingIn, Map<String, String> saslProps,
364	      CallbackHandler callbackHandler) throws IOException {
365	
366	    DataInputStream in = new DataInputStream(underlyingIn);
367	    DataOutputStream out = new DataOutputStream(underlyingOut);
368	
369	    int magicNumber = in.readInt();
370	    if (magicNumber != SASL_TRANSFER_MAGIC_NUMBER) {
