90	    int[] newPermitCounts = new int[] {6, 3, 6, 6};
91	
92	    if (manualRefresh) {
93	      controller.refreshPermitsCap();
94	    } else {
95	      Thread.sleep(5000);
96	    }
97	    verifyRemainingPermitCounts(newPermitCounts, nss, controller);
98	
99	  }
100	
101	  public void verifyDynamicControllerAllPermitsAcquired(boolean manualRefresh)
102	      throws InterruptedException {
103	    // 10 permits each ns
104	    DynamicRouterRpcFairnessPolicyController controller;
105	    if (manualRefresh) {
106	      controller = getFairnessPolicyController(40);
107	    } else {
108	      controller = getFairnessPolicyController(40, 4);
109	    }
110	
111	    String[] nss = new String[] {"ns1", "ns2", "ns3", CONCURRENT_NS};
112	    verifyRemainingPermitCounts(new int[] {10, 10, 10, 10}, nss, controller);
113	
114	    // Inject dummy metrics
115	    Map<String, LongAdder> rejectedPermitsPerNs = new HashMap<>();
116	    Map<String, LongAdder> acceptedPermitsPerNs = new HashMap<>();
117	    injectDummyMetrics(rejectedPermitsPerNs, "ns1", 13);
118	    injectDummyMetrics(rejectedPermitsPerNs, "ns2", 13);
119	    injectDummyMetrics(rejectedPermitsPerNs, "ns3", 13);
120	    injectDummyMetrics(rejectedPermitsPerNs, CONCURRENT_NS, 1);
121	    // New permit capacity will be 13:13:13:3
122	    controller.setMetrics(rejectedPermitsPerNs, acceptedPermitsPerNs);
123	    if (manualRefresh) {
124	      controller.refreshPermitsCap();
125	    } else {
126	      Thread.sleep(5000);
127	    }
128	    Assert.assertEquals("{\"concurrent\":-7,\"ns2\":3,\"ns1\":3,\"ns3\":3}",
129	        controller.getAvailableHandlerOnPerNs());
130	
131	    // Can acquire 3 more permits for ns1, ns2, ns3
132	    verifyRemainingPermitCounts(new int[] {3, 3, 3, 0}, nss, controller);
133	    // Need to release at least 8 permits for concurrent before it has any free permits
134	    Assert.assertFalse(controller.acquirePermit(CONCURRENT_NS));
135	    for (int i = 0; i < 7; i++) {
136	      controller.releasePermit(CONCURRENT_NS);
137	    }
138	    Assert.assertFalse(controller.acquirePermit(CONCURRENT_NS));
139	    controller.releasePermit(CONCURRENT_NS);
140	    Assert.assertTrue(controller.acquirePermit(CONCURRENT_NS));
141	  }
