143	  private void verifyRemainingPermitCounts(int[] remainingPermitCounts, String[] nss,
144	      RouterRpcFairnessPolicyController controller) {
145	    assert remainingPermitCounts.length == nss.length;
146	    for (int i = 0; i < remainingPermitCounts.length; i++) {
147	      verifyRemainingPermitCount(remainingPermitCounts[i], nss[i], controller);
148	    }
149	  }
150	
151	  private void verifyRemainingPermitCount(int remainingPermitCount, String nameservice,
152	      RouterRpcFairnessPolicyController controller) {
153	    for (int i = 0; i < remainingPermitCount; i++) {
154	      Assert.assertTrue(controller.acquirePermit(nameservice));
155	    }
156	    Assert.assertFalse(controller.acquirePermit(nameservice));
157	  }
