98	        Class<?> interceptorClass = conf.getClassByName(className);
99	        if (clazz.isAssignableFrom(interceptorClass)) {
100	          Object interceptorInstance =
101	              ReflectionUtils.newInstance(interceptorClass, conf);
102	          if (pipeline == null) {
103	            pipeline = clazz.cast(interceptorInstance);
104	            current = clazz.cast(interceptorInstance);
105	            continue;
106	          } else {
107	            Method method = clazz.getMethod("setNextInterceptor", clazz);
108	            method.invoke(current, interceptorInstance);
109	            current = clazz.cast(interceptorInstance);
110	          }
111	        } else {
112	          LOG.error("Class: {} not instance of {}.", className,
113	              clazz.getCanonicalName());
114	          throw new YarnRuntimeException("Class: " + className
115	              + " not instance of " + clazz.getCanonicalName());
116	        }
117	      } catch (ClassNotFoundException e) {
118	        LOG.error("Could not instantiate RequestInterceptor: {}", className, e);
119	        throw new YarnRuntimeException(
120	            "Could not instantiate RequestInterceptor: " + className, e);
121	      } catch (InvocationTargetException e) {
122	        LOG.error("RequestInterceptor {} call setNextInterceptor error.",
123	            className, e);
124	        throw new YarnRuntimeException("RequestInterceptor " + className
125	            + " call setNextInterceptor error.", e);
126	      } catch (NoSuchMethodException e) {
127	        LOG.error("RequestInterceptor {} does not contain the method "
128	            + "setNextInterceptor.", className);
129	        throw new YarnRuntimeException("RequestInterceptor " + className
130	            + " does not contain the method setNextInterceptor.", e);
131	      } catch (IllegalAccessException e) {
132	        LOG.error("RequestInterceptor {} call the method setNextInterceptor "
133	            + "does not have access.", className);
134	        throw new YarnRuntimeException("RequestInterceptor " + className
135	            + " call the method setNextInterceptor does not have access.", e);
136	      }
137	    }
138	
139	    if (pipeline == null) {
140	      throw new YarnRuntimeException(
141	          "RequestInterceptor pipeline is not configured in the system.");
142	    }
143	
144	    return pipeline;
145	  }
146	
147	  private static List<String> getInterceptorClassNames(Configuration conf,
148	      String pipeLineClass, String interceptorClass) {
149	    String configuredInterceptorClassNames =
150	        conf.get(pipeLineClass, interceptorClass);
151	    List<String> interceptorClassNames = new ArrayList<>();
152	    Collection<String> tempList =
153	        StringUtils.getStringCollection(configuredInterceptorClassNames);
154	    for (String item : tempList) {
155	      interceptorClassNames.add(item.trim());
156	    }
157	    return interceptorClassNames;
158	  }
