    HttpServletRequest hsr, String appId) throws AuthorizationException,
    YarnException, InterruptedException, IOException {
  long startTime = clock.getTime();

  if (appId == null || appId.isEmpty()) {
    routerMetrics.incrAppsFailedRetrieved();
    throw new YarnRuntimeException(
        "Parameter error, the appId is empty or null.");
  }
  if (appTimeout == null) {
    routerMetrics.incrAppsFailedRetrieved();
    throw new YarnRuntimeException(
        "Parameter error, the appTimeout is null.");
  }

  ApplicationId applicationId = null;
  try {
    applicationId = ApplicationId.fromString(appId);
  } catch (IllegalArgumentException e) {
    routerMetrics.incrAppsFailedRetrieved();
    return Response
        .status(Status.BAD_REQUEST)
        .entity(e.getLocalizedMessage())
        .build();
  }

  SubClusterInfo subClusterInfo = null;
  SubClusterId subClusterId = null;
  try {
    subClusterId =
        federationFacade.getApplicationHomeSubCluster(applicationId);
    if (subClusterId == null) {
      routerMetrics.incrAppsFailedRetrieved();
      return Response
          .status(Status.BAD_REQUEST)
          .entity("Application " + appId + " does not exist in StateStore.")
          .build();
    }
    subClusterInfo = federationFacade.getSubCluster(subClusterId);
  } catch (YarnException e) {
    routerMetrics.incrAppsFailedRetrieved();
    return Response
        .status(Status.BAD_REQUEST)
        .entity(e.getLocalizedMessage())
        .build();
  }

  Response response = getOrCreateInterceptorForSubCluster(subClusterId,
      subClusterInfo.getRMWebServiceAddress())
      .updateApplicationTimeout(appTimeout, hsr, appId);

  long stopTime = clock.getTime();
  routerMetrics.succeededAppsRetrieved(stopTime - startTime);

  return response;
}

