/**
 * The YARN Router will forward to the respective YARN RM in which the
 * container is running. The SubCluster is derived from the applicationId
 * embedded in the containerId.
 * <p>
 * Possible failure:
 * <p>
 * Client: identical behavior as {@code RMWebServices}.
 * <p>
 * Router: the Client will timeout and resubmit the request.
 * <p>
 * ResourceManager: the Router will timeout and the call will fail.
 * <p>
 * State Store: the Router will timeout and it will retry depending on the
 * FederationFacade settings - if the failure happened before the select
 * operation.
 */
@Override
public Response signalToContainer(String containerId, String command,
    HttpServletRequest req) {
  long startTime = clock.getTime();

  if (containerId == null || containerId.isEmpty()) {
    routerMetrics.incrAppsFailedRetrieved();
    throw new YarnRuntimeException(
        "Parameter error, the containerId is empty or null.");
  }
  if (command == null || command.isEmpty()) {
    routerMetrics.incrAppsFailedRetrieved();
    throw new YarnRuntimeException(
        "Parameter error, the command is empty or null.");
  }

  ApplicationId applicationId = null;
  try {
    ContainerId containerIdentifier = ContainerId.fromString(containerId);
    applicationId = containerIdentifier.getApplicationAttemptId()
        .getApplicationId();
  } catch (IllegalArgumentException e) {
    routerMetrics.incrAppsFailedRetrieved();
    return Response
        .status(Status.BAD_REQUEST)
        .entity(e.getLocalizedMessage())
        .build();
  }

  SubClusterInfo subClusterInfo = null;
  SubClusterId subClusterId = null;
  try {
    subClusterId =
        federationFacade.getApplicationHomeSubCluster(applicationId);
    if (subClusterId == null) {
      routerMetrics.incrAppsFailedRetrieved();
      return Response
          .status(Status.BAD_REQUEST)
          .entity("Application of container " + containerId
              + " does not exist in StateStore.")
          .build();
    }
    subClusterInfo = federationFacade.getSubCluster(subClusterId);
  } catch (YarnException e) {
    routerMetrics.incrAppsFailedRetrieved();
    return Response
        .status(Status.BAD_REQUEST)
        .entity(e.getLocalizedMessage())
        .build();
  }

  Response response = getOrCreateInterceptorForSubCluster(subClusterId,
      subClusterInfo.getRMWebServiceAddress())
      .signalToContainer(containerId, command, req);

  long stopTime = clock.getTime();
  routerMetrics.succeededAppsRetrieved(stopTime - startTime);

  return response;
}

